#!/usr/bin/env python3
"""把 Copilot 会话 transcript (JSONL) 转成可读的 Markdown。

用法: python3 export_transcript_md.py <input.jsonl> <output.md> [--reasoning] [--toolarg-len N]
"""
import json
import sys
import datetime

def ts_to_str(ts, with_date=True):
    if not ts:
        return ''
    try:
        dt = datetime.datetime.strptime(ts[:19], '%Y-%m-%dT%H:%M:%S')
        dt = dt + datetime.timedelta(hours=8)  # UTC -> 北京时间
        return dt.strftime('%Y-%m-%d %H:%M:%S' if with_date else '%H:%M:%S')
    except Exception:
        return ts


def trunc(s, n):
    if not isinstance(s, str):
        s = json.dumps(s, ensure_ascii=False)
    s = s.replace('\r\n', '\n')
    if n and len(s) > n:
        return s[:n] + f'\n…（已截断，原长 {len(s)} 字符）'
    return s


def main():
    src = sys.argv[1]
    dst = sys.argv[2]
    with_reasoning = '--reasoning' in sys.argv
    tool_len = 300
    if '--toolarg-len' in sys.argv:
        tool_len = int(sys.argv[sys.argv.index('--toolarg-len') + 1])

    out = []
    turn_no = 0
    pending_tools = []
    stats = {'user': 0, 'assistant': 0, 'tools': 0}

    with open(src, encoding='utf-8', errors='replace') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                d = json.loads(line)
            except Exception:
                continue
            t = d.get('type')
            data = d.get('data') or {}
            ts = d.get('timestamp', '')

            if t == 'session.start':
                out.append('# 会话记录：工作区架构和文档核对\n')
                out.append(f"- 会话 ID: `{data.get('sessionId')}`")
                out.append(f"- Copilot 版本: {data.get('copilotVersion')} / VS Code {data.get('vscodeVersion')}")
                out.append(f"- 开始时间: {ts_to_str(data.get('startTime'))}\n")
                out.append('---\n')

            elif t == 'user.message':
                turn_no += 1
                stats['user'] += 1
                content = data.get('content')
                if isinstance(content, list):
                    content = '\n'.join(
                        str(c.get('text', '')) if isinstance(c, dict) else str(c) for c in content)
                atts = data.get('attachments') or []
                att_names = []
                for a in atts:
                    if isinstance(a, dict):
                        att_names.append(str(a.get('label') or a.get('name') or a.get('filePath') or ''))
                out.append(f'\n## 👤 用户  [{ts_to_str(ts)}]\n')
                out.append('```text')
                out.append(trunc(content, 0))
                out.append('```')
                if att_names:
                    out.append('*附件: ' + ', '.join(x for x in att_names if x) + '*')

            elif t == 'assistant.message':
                stats['assistant'] += 1
                content = data.get('content')
                reasoning = data.get('reasoningText')
                reqs = data.get('toolRequests') or []
                block = []
                if content:
                    block.append(trunc(content, 0))
                if with_reasoning and reasoning:
                    block.append('\n<details><summary>💭 思考过程</summary>\n')
                    block.append('```text')
                    block.append(trunc(reasoning, 4000))
                    block.append('```')
                    block.append('</details>')
                if reqs:
                    lines = []
                    for r in reqs:
                        name = r.get('name', '?')
                        args = r.get('arguments', '')
                        lines.append(f"- `{name}`({trunc(args, tool_len).replace(chr(10), ' ')})")
                    block.append('\n**🔧 工具调用:**\n' + '\n'.join(lines))
                    stats['tools'] += len(reqs)
                if block:
                    out.append(f'\n### 🤖 助手  [{ts_to_str(ts)}]\n')
                    out.append('\n'.join(block))

            elif t == 'tool.execution_complete':
                pass  # 结果不导出，避免体积爆炸

    with open(dst, 'w', encoding='utf-8') as f:
        f.write('\n'.join(out))

    print(f'✅ 导出完成: {dst}')
    print(f'   用户消息 {stats["user"]} 条 / 助手消息 {stats["assistant"]} 条 / 工具调用 {stats["tools"]} 次')


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""生成会话精简版：保留全部用户消息 + 有实质内容的助手回复（截断）。

用法: python3 make_condensed.py <transcript.jsonl> <out.md> [assistant_min_len] [assistant_trunc]
"""
import json
import sys
import datetime


def ts_to_str(ts):
    if not ts:
        return ''
    try:
        dt = datetime.datetime.strptime(ts[:19], '%Y-%m-%dT%H:%M:%S')
        dt += datetime.timedelta(hours=8)
        return dt.strftime('%m-%d %H:%M')
    except Exception:
        return ts


def main():
    src, dst = sys.argv[1], sys.argv[2]
    amin = int(sys.argv[3]) if len(sys.argv) > 3 else 150
    atrunc = int(sys.argv[4]) if len(sys.argv) > 4 else 1200

    buf = []
    turn = 0
    with open(src, encoding='utf-8', errors='replace') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                d = json.loads(line)
            except Exception:
                continue
            t = d.get('type')
            data = d.get('data') or {}
            ts = ts_to_str(d.get('timestamp', ''))

            if t == 'user.message':
                turn += 1
                content = data.get('content')
                if isinstance(content, list):
                    content = '\n'.join(
                        str(c.get('text', '')) if isinstance(c, dict) else str(c) for c in content)
                content = (content or '').strip()
                buf.append(f'\n---\n\n### [{turn}] 👤 用户 ({ts})\n\n{content}\n')
            elif t == 'assistant.message':
                content = (data.get('content') or '').strip()
                if len(content) >= amin:
                    body = content if atrunc == 0 else content[:atrunc]
                    if atrunc and len(content) > atrunc:
                        body += f'\n…（截断，原长 {len(content)}）'
                    buf.append(f'\n**🤖 助手 ({ts})**\n\n{body}\n')

    with open(dst, 'w', encoding='utf-8') as f:
        f.write('\n'.join(buf))
    print(f'✅ {dst}')
    print(f'   轮数 {turn}')


if __name__ == '__main__':
    main()

