        except Exception:
            continue
        if o.get('kind') != 1:
            continue
        k = o.get('k') or []
        v = o.get('v')
        if not k:
            continue

        cur = state
        ok = True
        for i, part in enumerate(k[:-1]):
            nxt = k[i + 1]
            if isinstance(cur, list):
                idx = int(part)
                while len(cur) <= idx:
                    cur.append(None)
                if cur[idx] is None:
                    cur[idx] = [] if _is_index(nxt) else {}
                cur = cur[idx]
            elif isinstance(cur, dict):
                if part not in cur or cur[part] is None:
                    cur[part] = [] if _is_index(nxt) else {}
                cur = cur[part]
