                ok = False
                break
        if not ok:
            continue

        last = k[-1]
        if isinstance(cur, list):
            idx = int(last)
            while len(cur) <= idx:
                cur.append(None)
            cur[idx] = v
        elif isinstance(cur, dict):
            cur[last] = v
    return state


if __name__ == '__main__':
