New:
```c
static int stm32n6_video_start(void)
{
  FAR struct stm32n6_video_dev_s *priv = &g_stm32n6_video;
  uint32_t fbaddr;
  int ret;

  if (priv->streaming)
    {
      return OK;
    }

  fbaddr = stm32n6_board_get_framebuffer();
  if (fbaddr == 0)
    {
      verr("stm32n6_video: no framebuffer (CONFIG_VIDEO_FB?)\n");
      return -ENODEV;
    }

