   *     s = (d + 0.5) * scale - 0.5
   * and clamps the two taps it interpolates between.  Doing the same here
   * is what keeps the board's input bit-comparable with the PC reference.
   */

  for (oy = 0; oy < EYE_CAM_FACE_H; oy++)
    {
      float   fy = (oy + 0.5f) * sy - 0.5f;
      int     y0 = (int)floorf(fy);
      float   wy = fy - (float)y0;
      int     ox;

      if (y0 < 0) { y0 = 0; wy = 0.0f; }
      if (y0 > EYE_CAM_FRAME_H - 2) { y0 = EYE_CAM_FRAME_H - 2; wy = 1.0f; }

      FAR const uint16_t *row0 = fb + (size_t)y0 * (stride / 2);
      FAR const uint16_t *row1 = row0 + (stride / 2);

