```c
/****************************************************************************
 * Face detection
 *
 * The two stage pipeline the PC reference evaluates is
 *
 *   frame -> YuNet 256x416 int8 -> best anchor -> eye keypoints
 *         -> crop 1.8*dx wide, eye at 0.31 of its height
 *         -> 128x64 int8 classifier
 *
 * This block is the first half.  The detector is the same network at the
 * same resolution the reference uses, and the decoded quantity is the same
 * one: the score of the best anchor over all three strides, whose keypoint
 * head then gives the eye centre and the inter-pupillary distance.
 *
 * The reference never decodes a bounding box - it reads the keypoints of
 * the winning anchor directly - so the three bbox tensors are ignored and
 * there is no NMS.
 *
 *   sc = sqrt(clip(cls) * clip(obj))        (product is commutative, so
 *                                            either single value tensor can
 *                                            take either role)
 *   i  = argmax(sc) over the 1664/416/104 anchors of that stride
 *   if max(sc) < 0.6 there is no face this frame
 *
 * Keypoints come back quantised as (x, y) pairs relative to the anchor:
 *
 *   px = (anchor_col + kx) * stride * (800/416)
 *   py = (anchor_row + ky) * stride * (480/256)
 *
 * with kp[0] the right eye and kp[1] the left one.
 ****************************************************************************/

#define EYE_CAM_FACE_H          256
#define EYE_CAM_FACE_W          416
#define EYE_CAM_FACE_PLANE      (EYE_CAM_FACE_H * EYE_CAM_FACE_W)
#define EYE_CAM_FACE_IN_LEN     (3 * EYE_CAM_FACE_PLANE)      /* 319488 */
#define EYE_CAM_FACE_THR        0.6f

/* The eight keypoints-worth of layout is addressable through the pool the
 * driver hands out: status.output_addr is the base of the twelve tensors,
 * and the offsets below are the ones ST's generator assigned inside it.
 */

struct eye_cam_face_scale_s
{
  uint32_t nanchor;
  uint32_t stride;
  uint32_t off_a;
  uint32_t off_b;
  uint32_t off_kps;
  float    sc_a;
  float    sc_b;
  float    sc_kps;
  int32_t  zp_a;
  int32_t  zp_b;
  int32_t  zp_kps;
};

static const struct eye_cam_face_scale_s g_face_scale[3] =
{
  { 1664,  8, 449280,  16640,      0,
    0.0036890279f, 0.0039136480f, 0.0380033851f, -128, -128, -40 },
  {  416, 16, 575952, 576368, 565760,
    0.0023810691f, 0.0000037500f, 0.0050239060f, -128, -128, -112 },
  {  104, 32, 577200, 577312, 574912,
    0.0034092192f, 0.0039212201f, 0.0261975788f, -128, -128, -35 },
};

struct eye_cam_face_s
{
  float    score;
  uint32_t stride;
  uint32_t anchor;
  float    ex;          /* eye centre, frame pixels   */
  float    ey;
  float    dx;          /* inter-pupillary distance   */
  float    kp[10];      /* five keypoints, frame pixels */
};

/* Source positions of the resampler taps.  They only depend on the pixel
 * index, so they are worked out once rather than 106496 times a frame.
 */

static int   g_face_x0[EYE_CAM_FACE_W];
static float g_face_xw[EYE_CAM_FACE_W];
static int   g_face_y0[EYE_CAM_FACE_H];
static float g_face_yw[EYE_CAM_FACE_H];
static bool  g_face_taps_ready;

/****************************************************************************
 * Name: eye_cam_face_taps
 *
 * Description:
 *   Prepare the tap positions of the frame -> 256x416 resampler.
 *
 *   cv2 places an output sample at
 *
 *     s = (d + 0.5) * scale - 0.5
 *
 *   and interpolates between the two source samples that straddle it, so
 *   this is where the two taps sit and how they are weighted.
 *
 ***************************************************************************/

static void eye_cam_face_taps(void)
{
  float sx = (float)EYE_CAM_FRAME_W / (float)EYE_CAM_FACE_W;
  float sy = (float)EYE_CAM_FRAME_H / (float)EYE_CAM_FACE_H;
  int   d;

  for (d = 0; d < EYE_CAM_FACE_W; d++)
    {
      float s = ((float)d + 0.5f) * sx - 0.5f;
      int   i = (int)floorf(s);

      if (i < 0)
        {
          i = 0;
          s = 0.0f;
        }
      else if (i > EYE_CAM_FRAME_W - 2)
        {
          i = EYE_CAM_FRAME_W - 2;
          s = (float)i + 1.0f;
        }

      g_face_x0[d] = i;
      g_face_xw[d] = s - (float)i;
    }

  for (d = 0; d < EYE_CAM_FACE_H; d++)
    {
      float s = ((float)d + 0.5f) * sy - 0.5f;
      int   i = (int)floorf(s);

      if (i < 0)
        {
          i = 0;
          s = 0.0f;
        }
      else if (i > EYE_CAM_FRAME_H - 2)
        {
          i = EYE_CAM_FRAME_H - 2;
          s = (float)i + 1.0f;
        }

      g_face_y0[d] = i;
      g_face_yw[d] = s - (float)i;
    }

  g_face_taps_ready = true;
}
```

