**decode 函数：**

```c
/****************************************************************************
 * Name: eye_cam_face_decode
 *
 * Description:
 *   Score every anchor of the three strides and keep the best one, then
 *   read its keypoints.  Returns true when a face was found.
 *
 ***************************************************************************/

static bool eye_cam_face_decode(FAR const int8_t *pool,
                               FAR struct eye_cam_face_s *out)
{
  float    best_sc = -1.0f;
  uint32_t best_st = 0;
  uint32_t best_i  = 0;
  uint32_t s;

  for (s = 0; s < 3; s++)
    {
      FAR const struct eye_cam_face_scale_s *sc = &g_face_scale[s];
      FAR const int8_t *pa = pool + sc->off_a;
      FAR const int8_t *pb = pool + sc->off_b;
      uint32_t i;

      for (i = 0; i < sc->nanchor; i++)
        {
          float va = ((float)pa[i] - (float)sc->zp_a) * sc->sc_a;
          float vb = ((float)pb[i] - (float)sc->zp_b) * sc->sc_b;
          float v;

          /* The reference clips both factors into 0..1 before multiplying
           * (they are sigmoid outputs, and int8 rounding can push a
           * saturated one slightly past 1).
           */

          if (va < 0.0f) va = 0.0f;  else if (va > 1.0f) va = 1.0f;
          if (vb < 0.0f) vb = 0.0f;  else if (vb > 1.0f) vb = 1.0f;

          v = sqrtf(va * vb);

          if (v > best_sc)
            {
              best_sc = v;
              best_st = s;
              best_i  = i;
            }
        }
    }

  if (best_sc < EYE_CAM_FACE_THR)
    {
      return false;
    }

  {
    FAR const struct eye_cam_face_scale_s *sc = &g_face_scale[best_st];
    FAR const int8_t *kps = pool + sc->off_kps +
                            (size_t)best_i * 10;
    uint32_t cols = EYE_CAM_FACE_W / sc->stride;
    uint32_t row  = best_i / cols;
    uint32_t col  = best_i % cols;
    float    sx   = (float)EYE_CAM_FRAME_W / (float)EYE_CAM_FACE_W;
    float    sy   = (float)EYE_CAM_FRAME_H / (float)EYE_CAM_FACE_H;
    int      k;

    for (k = 0; k < 5; k++)
      {
        float kx = ((float)kps[2 * k] - (float)sc->zp_kps) * sc->sc_kps;
        float ky = ((float)kps[2 * k + 1] - (float)sc->zp_kps) * sc->sc_kps;

        out->kp[2 * k]     = ((float)col + kx) * (float)sc->stride * sx;
        out->kp[2 * k + 1] = ((float)row + ky) * (float)sc->stride * sy;
      }

    out->score  = best_sc;
    out->stride = sc->stride;
    out->anchor = best_i;
    out->ex     = (out->kp[0] + out->kp[2]) * 0.5f;
    out->ey     = (out->kp[1] + out->kp[3]) * 0.5f;
    out->dx     = fabsf(out->kp[2] - out->kp[0]);
  }

  return true;
}
```

**注意 kps 的 zp**：kps 张量的 zp = -40/-112/-35，**不是 -128**！所以 kx/ky 可以是负数（相对 anchor 的偏移）✓

**kp[0] = 右眼，kp[1..2] = 左眼** ✓
- `out->kp[0], out->kp[1]` = 右眼 (x,y)
- `out->kp[2], out->kp[3]` = 左眼 (x,y)
- ex = (kp[0]+kp[2])/2, ey = (kp[1]+kp[3])/2 ✓
- dx = |kp[2]-kp[0]| ✓

