**函数 1：BMP 小工具**
```c
static void eye_cam_cap_put_u16(FAR uint8_t *p, uint16_t v)
{
  p[0] = (uint8_t)(v & 0xff);
  p[1] = (uint8_t)((v >> 8) & 0xff);
}

static void eye_cam_cap_put_u32(FAR uint8_t *p, uint32_t v)
{
  p[0] = (uint8_t)(v & 0xff);
  p[1] = (uint8_t)((v >> 8) & 0xff);
  p[2] = (uint8_t)((v >> 16) & 0xff);
  p[3] = (uint8_t)((v >> 24) & 0xff);
}
```

**函数 2：BMP 头**
```c
static void eye_cam_cap_header(FAR FILE *fp, int w, int h, uint32_t imgsz)
{
  FAR uint8_t hdr[54];
  uint32_t off = 54;

  memset(hdr, 0, sizeof(hdr));
  hdr[0] = 'B';
  hdr[1] = 'M';
  eye_cam_cap_put_u32(&hdr[2], off + imgsz);
  eye_cam_cap_put_u32(&hdr[10], off);
  eye_cam_cap_put_u32(&hdr[14], 40);
  eye_cam_cap_put_u32(&hdr[18], (uint32_t)w);
  eye_cam_cap_put_u32(&hdr[22], (uint32_t)h);
  eye_cam_cap_put_u16(&hdr[26], 1);
  eye_cam_cap_put_u16(&hdr[28], 24);
  eye_cam_cap_put_u32(&hdr[34], imgsz);
  eye_cam_cap_put_u32(&hdr[38], 2835);
  eye_cam_cap_put_u32(&hdr[42], 2835);
  fwrite(hdr, 1, sizeof(hdr), fp);
}
```

**函数 3：单行转换（1:1，越界填黑）**
```c
static void eye_cam_cap_row(FAR const uint16_t *fb, uint32_t stride,
                            int rx, int ry, int rw, int y,
                            FAR uint8_t *row)
{
  uint32_t stride_px = stride / 2;
  int sy = ry + y;

  if (sy < 0 || sy >= EYE_CAM_FRAME_H)
    {
      memset(row, 0, (size_t)rw * 3);
      return;
    }

  {
    FAR const uint16_t *srow = &fb[(size_t)sy * stride_px];
    int x;

    for (x = 0; x < rw; x++)
      {
        int sx = rx + x;
        uint16_t px = 0;
        uint8_t r;
        uint8_t g;
        uint8_t b;

        if (sx >= 0 && sx < EYE_CAM_FRAME_W)
          {
            px = srow[sx];
          }

        /* Expand with the same tables the classifier's input uses, so a
         * pixel has one meaning across the whole app.
         */

        r = g_exp5[(px >> 11) & 0x1f];
        g = g_exp6[(px >> 5) & 0x3f];
        b = g_exp5[px & 0x1f];

        row[x * 3 + 0] = b;       /* BMP order is B, G, R */
        row[x * 3 + 1] = g;
        row[x * 3 + 2] = r;
      }
  }
}
```

