  int n;

  for (n = 1; n < 10000; n++)
    {
      snprintf(path, sizeof(path), "%s/%s_%04d.bmp",
               EYE_CAM_CAP_DIR, label, n);

      fp = fopen(path, "rb");
      if (fp == NULL)
