**函数 5：存一张**
```c
static int eye_cam_cap_save(FAR const char *label, int seq,
                            FAR const struct eye_cam_face_s *face,
                            FAR FILE *meta)
{
  char path[128];
  FAR uint8_t *row;
  FILE *fp;
  int rw = g_crop_w;
  int rh = g_crop_h;
  int rowsz;
  uint32_t imgsz;
  int y;

  if (rw <= 0 || rh <= 0 || rw > EYE_CAM_CAP_MAX_W || rh > EYE_CAM_CAP_MAX_H)
    {
      return -EINVAL;
    }

  rowsz = (rw * 3 + 3) & ~3;
  imgsz = (uint32_t)rowsz * (uint32_t)rh;

  row = malloc(rowsz);
  if (row == NULL)
    {
      return -ENOMEM;
    }

  memset(row, 0, rowsz);        /* BMP pad bytes must not leak heap */
  snprintf(path, sizeof(path), "%s/%s_%04d.bmp", EYE_CAM_CAP_DIR, label, seq);

  fp = fopen(path, "wb");
  if (fp == NULL)
    {
      free(row);
      return -errno;
    }

  eye_cam_cap_header(fp, rw, rh, imgsz);

  for (y = rh - 1; y >= 0; y--)
    {
      eye_cam_cap_row(g_fb, g_stride_px * 2, g_crop_x, g_crop_y, rw, y, row);

      if (fwrite(row, 1, rowsz, fp) != (size_t)rowsz)
        {
          break;
        }
    }

  fclose(fp);
  free(row);

  /* One line per frame in meta.txt: the crop the model was given, and
   * where the detector had put it.  A frame whose box is off can then be
   * filtered on the PC without opening a single image.
   */

  if (meta != NULL)
    {
      fprintf(meta, "%s %04d %d %d %d %d %.3f %.1f %.1f %.1f\n",
              label, seq, g_crop_x, g_crop_y, rw, rh,
              (double)face->score, (double)face->ex, (double)face->ey,
              (double)face->dx);
      fflush(meta);
    }

  return 0;
}
