#!/usr/bin/env python3
"""Measure ink extents of glyphs in the GBK dot-matrix fonts.

The point is to pick sane metrics for the generated LVGL font:
  * where the baseline sits,
  * how much of the cell the ink actually occupies,
  * how much blank margin trimming would save.

Runs over a sample of level-1 GB2312 ideographs (GBK 0xB0A1 .. 0xD7F9 range).
"""
import collections
import os
import sys

FONT_DIR = "/home/leihann/SoftwarePackage/5\uff0cSD\u5361\u6839\u76ee\u5f55\u6587\u4ef6/SYSTEM/FONT"


def gbk_index(high, low):
    return (high - 0x81) * 190 + (low - 0x40) - (1 if low > 0x7F else 0)


def ink_box(bitmap, size):
    """Return (x0, y0, x1, y1) of inked pixels, or None if blank."""
    bpr = (size + 7) // 8
    x0, y0, x1, y1 = size, size, -1, -1
    for r in range(size):
        row = bitmap[r * bpr:(r + 1) * bpr]
        for byte_i, byte in enumerate(row):
            if not byte:
                continue
            for bit in range(8):
                if byte & (0x80 >> bit):
                    c = byte_i * 8 + bit
                    if c >= size:
                        continue
                    if c < x0:
                        x0 = c
                    if c > x1:
                        x1 = c
                    if r < y0:
                        y0 = r
                    if r > y1:
                        y1 = r
    if x1 < 0:
        return None
    return (x0, y0, x1, y1)


def main():
    sizes = [int(a) for a in sys.argv[1:] if a.isdigit()] or [32, 24]

    for size in sizes:
        path = os.path.join(FONT_DIR, "GBK%d.FON" % size)
        data = open(path, "rb").read()
        bpc = size * ((size + 7) // 8)

        y0s = collections.Counter()
        y1s = collections.Counter()
        wids = collections.Counter()
        blank = 0
        total = 0

        # level-1 GB2312 ideographs: high 0xB0..0xD7, low 0xA1..0xFE
        for high in range(0xB0, 0xD8):
            for low in range(0xA1, 0xFF):
                idx = gbk_index(high, low)
                off = idx * bpc
                if off + bpc > len(data):
                    continue
                box = ink_box(data[off:off + bpc], size)
                total += 1
                if box is None:
                    blank += 1
                    continue
                x0, y0, x1, y1 = box
                y0s[y0] += 1
                y1s[y1] += 1
                wids[x1 - x0 + 1] += 1

        print("=" * 62)
        print("GBK%d.FON   sampled %d glyphs   blank=%d" % (size, total, blank))
        print("=" * 62)

        print("\n  top edge (y0) distribution:")
        for v, c in sorted(y0s.items())[:8]:
            print("    y0=%2d  %5d  %s" % (v, c, "#" * min(50, c // 20)))

        print("\n  bottom edge (y1) distribution (last few):")
        for v, c in sorted(y1s.items())[-8:]:
            print("    y1=%2d  %5d  %s" % (v, c, "#" * min(50, c // 20)))

        print("\n  ink width distribution (top few):")
        for v, c in sorted(wids.items(), key=lambda kv: -kv[1])[:6]:
            print("    w =%2d  %5d" % (v, c))

        used = sum(v * c for v, c in wids.items()) / max(1, sum(wids.values()))
        print("\n  mean ink width       : %.1f px  (cell = %d px)" % (used, size))
        print("  mean rows saved (top) : %.1f" % (sum(y0s) / max(1, total)))
        print()


if __name__ == "__main__":
    main()

