/****************************************************************************
 * Eye-control panel (LVGL)
 *
 * A grid of square cells rather than a list: gaze moves in discrete steps,
 * so one look-left/right lands exactly on the next cell.  With the panel
 * refreshing at a couple of frames per second a six-row list would need
 * five separate dwells to reach the last entry.
 *
 * The panel owns the panel-side framebuffer exclusively.  The camera writes
 * the very same buffer (see the header), so this mode must not start the
 * capture stream.  Keeping the two mutually exclusive is what makes the
 * single-buffer design safe; a mixed mode has to freeze the stream first.
 ****************************************************************************/

#if defined(CONFIG_GRAPHICS_LVGL)

#define EYE_UI_COLS          3
#define EYE_UI_ROWS          2
#define EYE_UI_COUNT         (EYE_UI_COLS * EYE_UI_ROWS)
#define EYE_UI_GAP           16
#define EYE_UI_MARGIN_X      30
#define EYE_UI_MARGIN_TOP    58
#define EYE_UI_MARGIN_BOT    46
#define EYE_UI_ICON_TOP      26
#define EYE_UI_LABEL_TOP     112
#define EYE_UI_POLL_MS       5

/* Every glyph below is in eye_ui_font_*; the list is baked into flash, so
 * a character that was not generated shows as nothing at all.
 */

static FAR const char *g_ui_icon[EYE_UI_COUNT] =
{
  "眼", "灯", "拍", "讯", "串", "问"
};

static FAR const char *g_ui_text[EYE_UI_COUNT] =
{
  "相机预览", "LED 控制", "拍照", "系统信息", "串口命令", "关于"
};

static FAR lv_obj_t *g_ui_cell[EYE_UI_COUNT];
static FAR lv_obj_t *g_ui_icon_lbl[EYE_UI_COUNT];
static FAR lv_obj_t *g_ui_text_lbl[EYE_UI_COUNT];
static int           g_ui_sel;
```

