#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Extract a compact, chronological view of a Copilot Chat transcript (JSONL)."""
import json
import sys

P = ("/home/leihann/.config/Code/User/workspaceStorage/"
     "202a05467ceff63220c526b288d9ea8b/GitHub.copilot-chat/transcripts/"
     "82658641-bed1-488c-821d-f499b50fbc97.jsonl")

MODE = sys.argv[1] if len(sys.argv) > 1 else "all"
TRUNC = int(sys.argv[2]) if len(sys.argv) > 2 else 700

lines = open(P, encoding="utf-8", errors="replace").read().splitlines()
print("### total lines:", len(lines))


def text_of(c, depth=0):
    if depth > 4:
        return "..."
    if c is None:
        return ""
    if isinstance(c, str):
        return c
    if isinstance(c, list):
        return "\n".join(text_of(x, depth + 1) for x in c)
    if isinstance(c, dict):
        t = c.get("type") or c.get("kind")
        if t == "text" or "text" in c:
            return c.get("text", "")
        if t == "tool_use" or "toolName" in c:
            name = c.get("name") or c.get("toolName") or "?"
            inp = c.get("input") or c.get("parameters") or c.get("args") or {}
            try:
                s = json.dumps(inp, ensure_ascii=False)
            except Exception:
                s = str(inp)
            return "<<TOOL %s>> %s" % (name, s)
        if t == "tool_result":
            inner = c.get("content")
            return "<<RESULT>> " + text_of(inner, depth + 1)
        if "content" in c:
            return text_of(c["content"], depth + 1)
        if "message" in c:
            return text_of(c["message"], depth + 1)
        return ""
    return str(c)


def role_of(d):
    if not isinstance(d, dict):
        return ("?", d)
    for k in ("role", "type"):
        if k in d:
            return (d[k], d)
    v = d.get("v")
    if isinstance(v, dict):
        for k in ("role", "type"):
            if k in v:
                return (v[k], v)
        for sub in ("message", "request", "response"):
            if isinstance(v.get(sub), dict):
                for k in ("role", "type"):
                    if k in v[sub]:
                        return ("%s/%s" % (sub, v[sub][k]), v[sub])
    for sub in ("message", "request", "response"):
        if isinstance(d.get(sub), dict):
            for k in ("role", "type"):
                if k in d[sub]:
                    return ("%s/%s" % (sub, d[sub][k]), d[sub])
    return ("?", d)


if MODE == "schema":
    for i in range(min(6, len(lines))):
        try:
            d = json.loads(lines[i])
        except Exception as e:
            print(i, "PARSE-ERR", e, lines[i][:200])
            continue
        print("---", i, "keys=", list(d.keys()) if isinstance(d, dict) else type(d))
        print("    ", json.dumps(d, ensure_ascii=False)[:900])
    sys.exit(0)

# ---- main extraction ----
recs = []
for i, l in enumerate(lines):
    try:
        d = json.loads(l)
    except Exception:
        continue
    r, obj = role_of(d)
    tx = text_of(obj)
    tx = tx.strip()
    if not tx:
        continue
    recs.append((i, r, tx))

print("### records with text:", len(recs))
lo = int(sys.argv[3]) if len(sys.argv) > 3 else 0
for i, r, tx in recs:
    if i < lo:
        continue
    show = tx if len(tx) <= TRUNC else tx[:TRUNC] + "  ...[%d chars total]" % len(tx)
    print("\n===== L%-5d [%s] =====" % (i, r))
    print(show)

