 *   Run as "eye_cam xspitest".
 *
 ****************************************************************************/

static int eye_cam_xspi_probe(void)
{
  FAR volatile uint32_t *base = (FAR volatile uint32_t *)0x90000000;
  uint32_t val;

  syslog(LOG_INFO, "xspi-probe: step 1 - read 0x90000000\n");
  val = base[0];
  syslog(LOG_INFO, "xspi-probe: step 1 ok, value 0x%08lx\n",
         (unsigned long)val);

  syslog(LOG_INFO, "xspi-probe: step 2 - read 0x90000004\n");
  val = base[1];
  syslog(LOG_INFO, "xspi-probe: step 2 ok, value 0x%08lx\n",
         (unsigned long)val);

  syslog(LOG_INFO, "xspi-probe: step 3 - read 0x90040000\n");
  val = base[0x10000];
  syslog(LOG_INFO, "xspi-probe: step 3 ok, value 0x%08lx\n",
         (unsigned long)val);

  syslog(LOG_INFO, "xspi-probe: step 4 - write 0xa5a5a5a5 to 0x90000000\n");
  base[0] = 0xa5a5a5a5;
  syslog(LOG_INFO, "xspi-probe: step 4 posted (no fault yet)\n");

  /* A posted write only reports asynchronously; force the write buffer to
   * drain by reading back something that is definitely not the same address.
   */

  syslog(LOG_INFO, "xspi-probe: step 5 - read back 0x90000000\n");
  val = base[0];
  syslog(LOG_INFO, "xspi-probe: step 5 ok, value 0x%08lx (want a5a5a5a5)\n",
         (unsigned long)val);

  if (val != 0xa5a5a5a5)
    {
      syslog(LOG_INFO, "xspi-probe: WRITE DID NOT STICK\n");
    }
  else
    {
      syslog(LOG_INFO, "xspi-probe: read/write round trip OK\n");
    }

  syslog(LOG_INFO, "xspi-probe: done\n");
  return 0;
}
