```c
/****************************************************************************
 * Name: eye_ui_verdict
 *
 * Description:
 *   Debounce the classifier verdict and act on it.  The hold is measured in
 *   time, not in frames: the capture loop runs at whatever rate the pipeline
 *   manages, so a frame count would mean a different glance duration every
 *   time the load changes.  A verdict has to hold continuously - one stray
 *   "other" restarts the timer - and nothing is accepted for EYE_UI_COOLDOWN
 *   after a trigger, which is what stops a single long glance from stepping
 *   through the whole grid.
 *
 ****************************************************************************/

static void eye_ui_verdict(int cls, int conf)
{
  clock_t now = clock_systime_ticks();
  clock_t hold;

  if (now < g_ui_cooldown_until)
    {
      g_ui_tracking = false;
      return;
    }

  if (!g_ui_tracking || cls != g_ui_last)
    {
      g_ui_last     = cls;
      g_ui_since    = now;
      g_ui_tracking = true;

      eye_cam_out("eye_ui: %s (%d%%) - holding\n",
                  g_ui_name[cls], conf);
      return;
    }

  hold = MSEC2TICK(cls == EYE_CAM_CLS_CLOSED ? EYE_UI_HOLD_OK :
                                               EYE_UI_HOLD_NAV);

  if ((now - g_ui_since) < hold)
    {
      return;
    }

  g_ui_tracking       = false;
  g_ui_cooldown_until = now + MSEC2TICK(EYE_UI_COOLDOWN);

  if (cls == EYE_CAM_CLS_LEFT || cls == EYE_CAM_CLS_RIGHT)
    {
      int sel = g_ui_sel + (cls == EYE_CAM_CLS_RIGHT ? 1 : -1);

      if (sel < 0)
        {
          sel = EYE_UI_COUNT - 1;
        }
      else if (sel >= EYE_UI_COUNT)
        {
          sel = 0;
        }

      eye_cam_out("eye_ui: MOVE %s -> %d (%s)\n",
                  cls == EYE_CAM_CLS_RIGHT ? "right" : "left", sel,
                  g_ui_text[sel]);
      eye_ui_highlight(sel);
    }
  else if (cls == EYE_CAM_CLS_CLOSED)
    {
      eye_cam_out("eye_ui: CONFIRM %d (%s)\n", g_ui_sel, g_ui_text[g_ui_sel]);
    }
}
```

