# --------------------------------------------- capture buffer + panel start
rep("""  g_fb        = (FAR uint16_t *)(uintptr_t)pinfo.fbmem;
  g_stride_px = pinfo.stride / 2;
""",
    """  g_fb        = (FAR uint16_t *)(uintptr_t)pinfo.fbmem;
  g_stride_px = pinfo.stride / 2;

#if defined(CONFIG_GRAPHICS_LVGL)
  if (g_ui_mode)
    {
