        }
    }
#endif
""",
    "capture buffer + panel start")

# ------------------------------------------------------- feed the verdict
rep("""        top = s[best];
        for (k = 0; k < EYE_CAM_NCLS; k++)
          {
            p[k] = expf(s[k] - top);
            sum += p[k];
          }
""",
    """        top = s[best];
        for (k = 0; k < EYE_CAM_NCLS; k++)
          {
