#endif
""",
    "feed the verdict")

# ------------------------------------------------------------ panel teardown
rep("""  eye_cam_out("eye_cam: done\\n");

  ioctl(vfd, VIDIOC_STREAMOFF, &type);
  close(fbfd);
""",
    """  eye_cam_out("eye_cam: done\\n");

#if defined(CONFIG_GRAPHICS_LVGL)
  if (g_ui_mode)
