static void eye_ui_led_open(void)
{
  if (g_led_fd < 0)
    {
      g_led_fd = open("/dev/userleds", O_WRONLY);
    }

  if (g_led_fd >= 0)
    {
      uint32_t all = 0;
      if (ioctl(g_led_fd, ULEDIOC_GETALL, (unsigned long)&all) == 0)
        {
          g_led_state = all;
        }
    }
}

static void eye_ui_led_toggle(int idx)
{
  struct userled_s led;

  if (g_led_fd < 0) return;

  led.ul_led = (uint8_t)idx;
  led.ul_on  = (g_led_state & (1u << idx)) == 0;

  if (ioctl(g_led_fd, ULEDIOC_SETLED, (unsigned long)&led) == 0)
    {
      if (led.ul_on) g_led_state |= (1u << idx);
      else           g_led_state &= ~(1u << idx);
    }
}
```

