```c
static void eye_ui_feed(int cls, int conf)
{
  int64_t now = eye_ui_ms();
  int64_t hold;
  int     sub;
  int     old;
  int     sel;

  if (now < g_ui_cooldown_until)
    {
      g_ui_tracking = false;
      return;
    }

  if (!g_ui_tracking || cls != g_ui_last)
    {
      g_ui_last     = cls;
      g_ui_since    = now;
      g_ui_tracking = true;
      return;
    }

  if (cls == EYE_CAM_CLS_OPEN || cls == EYE_CAM_CLS_OTHER)
    {
      return;
    }

  /* How long this verdict has to hold depends on what it will do, and that
   * depends on the page: on the menu left/right step through the grid, but
   * on a page left means "go back" and is given longer so a glance at the
   * previous cell does not throw the user out.
   */

  if (g_ui_page != EYE_UI_PAGE_GRID && cls == EYE_CAM_CLS_LEFT)
    {
      hold = EYE_UI_HOLD_BACK;
    }
  else
    {
      hold = (cls == EYE_CAM_CLS_CLOSED) ? EYE_UI_HOLD_OK : EYE_UI_HOLD_NAV;
    }

  if ((now - g_ui_since) < hold)
    {
      return;
    }

  g_ui_tracking       = false;
  g_ui_cooldown_until = now + EYE_UI_COOLDOWN;

  /* ---- sub-pages first: left is "back", everything else is local ------- */

  if (g_ui_page != EYE_UI_PAGE_GRID)
    {
      if (cls == EYE_CAM_CLS_LEFT)
        {
          eye_cam_out("eye_ui: BACK to the menu\n");
          eye_ui_page_enter(EYE_UI_PAGE_GRID);
          return;
        }

      if (cls == EYE_CAM_CLS_RIGHT)
        {
          sel = (g_ui_sel + 1) % g_ui_cells;
          eye_cam_out("eye_ui: next %d -> %d\n", g_ui_sel, sel);
          eye_ui_highlight(sel);
          return;
        }

      /* closed: act on the current cell */

      if (g_ui_page == EYE_UI_PAGE_LED)
        {
          if (g_ui_sel < EYE_UI_LED_CELLS - 1)
            {
              eye_ui_led_toggle(g_ui_sel);
              ... refresh texts, print
            }
          else
            {
              eye_ui_page_enter(EYE_UI_PAGE_GRID);
            }
        }
      else
        {
          if (g_ui_sel >= EYE_UI_INFO_CELLS - 1)
            {
              eye_ui_page_enter(EYE_UI_PAGE_GRID);
            }
          else
            {
              eye_ui_page_enter(EYE_UI_PAGE_INFO);   /* refresh values */
            }
        }

      return;
    }

  /* ---- menu grid ------------------------------------------------------- */

  if (cls == EYE_CAM_CLS_CLOSED)
    {
      old = g_ui_sel;

      if (old == 1)          /* LED 控制 */
        {
          eye_ui_page_enter(EYE_UI_PAGE_LED);
        }
      else if (old == 3)     /* 系统信息 */
        {
          eye_ui_page_enter(EYE_UI_PAGE_INFO);
        }
      else
        {
          eye_cam_out("eye_ui: OPEN %d %s - not implemented yet\n",
                      old, g_ui_text[old]);
        }

      return;
    }

  old = g_ui_sel;
  sel = old + (cls == EYE_CAM_CLS_RIGHT ? 1 : -1);
  ...
  eye_ui_highlight(sel);
}
```

