#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Turn a Copilot transcript into something a human can actually read.

The raw JSONL is dominated by tool results - a single pasted board log can be
megabytes - while the parts that carry the thread of a conversation are small:
what the user asked for, which tools ran, and what the assistant concluded.

So this walks the transcript once, groups events into turns (a turn runs from
one user message to the next), and prints:

    USER   <what was asked>
    ...[N attachments, X KB]...
    ACT    <tool> <key argument>       x however many
    SAY    <what the assistant concluded>

Tool *results* are deliberately dropped.  Everything else is truncated to a
budget that keeps the output readable rather than exhaustive.
"""
import json
import sys

SAY_LIMIT = 500     # characters of the assistant's concluding text
USER_LIMIT = 800    # characters of each user message
ACT_ARG = 90        # characters of each tool argument


def summarize_tool(data):
    """One line describing a tool call: its name and what it was aimed at."""

    name = data.get("toolName") or data.get("name") or "?"

    args = data.get("arguments") or data.get("input") or {}
    if isinstance(args, str):
        try:
            args = json.loads(args)
        except Exception:
            args = {"raw": args}

    # The interesting field differs per tool, and unnamed arguments are the
    # norm, so just take the first few values in order.
    bits = []
    for k in ("command", "filePath", "path", "query", "urls", "explanation",
              "goal", "symbol", "dirPath"):
        if k in args:
            v = args[k]
            if isinstance(v, list):
                v = ", ".join(str(x) for x in v)
            bits.append(str(v))

    if not bits:
        bits = [str(v) for v in list(args.values())[:2]]

    arg = " ".join(bits).replace("\n", " ").replace("\r", "")
    while "  " in arg:
        arg = arg.replace("  ", " ")

    return "%s: %s" % (name, arg[:ACT_ARG])


def emit(path, out):
    turns = []
    cur = None

    for line in open(path, encoding="utf-8", errors="replace"):
        line = line.strip()
        if not line:
            continue

        try:
            o = json.loads(line)
        except Exception:
            continue

        t = o.get("type")
        d = o.get("data") or {}
        ts = (o.get("timestamp") or "")[:19].replace("T", " ")

        if t == "user.message":
            cur = {"ts": ts, "user": d.get("content") or "", "atts": d.get("attachments") or [],
                   "acts": [], "says": []}
            turns.append(cur)

        elif cur is None:
            continue

        elif t == "tool.execution_start":
            cur["acts"].append(summarize_tool(d))

        elif t == "assistant.message":
            c = d.get("content") or ""
            if isinstance(c, list):
                c = " ".join(str(x) for x in c)
            c = c.strip()
            if c:
                cur["says"].append(c)

    total = 0
    for tn in turns:
        user = " ".join(tn["user"].split())

        # "Continue: ..." is an automated nudge, not a real instruction.
        if user.startswith("Continue:") and len(user) < 60:
            continue

        out.write("\n%s\n" % ("=" * 78))
        out.write("USER [%s] %s\n" % (tn["ts"], user[:USER_LIMIT]))

        if tn["atts"]:
            sizes = 0
            for a in tn["atts"]:
                if isinstance(a, dict):
                    sizes += len(json.dumps(a, ensure_ascii=False))
                else:
                    sizes += len(str(a))
            out.write("     ...%d attachment(s), %d KB...\n"
                      % (len(tn["atts"]), sizes // 1024))

        for a in tn["acts"][:40]:
            out.write("  ACT  %s\n" % a)
        if len(tn["acts"]) > 40:
            out.write("  ACT  ...(%d more)\n" % (len(tn["acts"]) - 40))

        if tn["says"]:
            # The last thing said before the user spoke again is the conclusion.
            out.write("  SAY  %s\n"
                      % " ".join(tn["says"][-1].split())[:SAY_LIMIT])

        total += 1

    return total


if __name__ == "__main__":
    src, dst = sys.argv[1], sys.argv[2]
    with open(dst, "w", encoding="utf-8") as fh:
        n = emit(src, fh)
    print("%s -> %s (%d turns)" % (src, dst, n))

