/****************************************************************************
 * Name: stm32n6_buzzer_beep
 *
 * Description:
 *   Sound the buzzer for the given number of milliseconds.  Blocking, by
 *   design: the callers are short prompts from the user interface, and the
 *   camera runs at a few frames per second anyway.
 *
 ****************************************************************************/

void stm32n6_buzzer_beep(uint32_t ms)
{
  if (ms == 0)
    {
      return;
    }

  stm32n6_gpiowrite(GPIO_BEEP, true);
  up_mdelay(ms);
  stm32n6_gpiowrite(GPIO_BEEP, false);
}

/****************************************************************************
 * Name: stm32n6_buzzer_beeps
 *
 * Description:
 *   Sound a short pattern: count beeps of on_ms each, separated by gap_ms of
 *   silence.  Patterns are what gives the interface a vocabulary - one beep
 *   for a confirmation, two for going back, and so on.
 *
 ****************************************************************************/

void stm32n6_buzzer_beeps(int count, uint32_t on_ms, uint32_t gap_ms)
{
  int i;

  for (i = 0; i < count; i++)
    {
      if (i > 0 && gap_ms > 0)
        {
          up_mdelay(gap_ms);
        }

      stm32n6_gpiowrite(GPIO_BEEP, true);
      up_mdelay(on_ms);
      stm32n6_gpiowrite(GPIO_BEEP, false);
    }
}
