#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Add a tone generator to the buzzer, and a command to test it with.

Whether the board's buzzer can change pitch depends on which kind it is: a
passive one follows the square wave it is given, an active one has its own
oscillator and ignores it.  The schematic shows only a designator, so the
answer has to come from the ear - two tones four octaves apart is the test.

The generator itself is what the interface will want either way: the eye
verdicts are meant to sound different notes.
"""
import sys


def read(path):
  return open(path, encoding="utf-8").read().split("\n")


def write(path, lines):
  open(path, "w", encoding="utf-8").write("\n".join(lines))


def find(lines, marker, start=0):
  for i in range(start, len(lines)):
    if marker in lines[i]:
      return i
  print("FAIL: anchor not found: %s" % marker)
  sys.exit(1)


# ------------------------------------------------------- the generator
P = ("/home/leihann/openvela/vendor/openvela/boards/atk-dnn647/src/"
     "stm32n6_buzzer.c")
lines = read(P)

if "stm32n6_buzzer_tone" in "\n".join(lines):
  print("stm32n6_buzzer.c: already there")
else:
  lines += """
/****************************************************************************
 * Name: stm32n6_buzzer_tone
 *
 * Description:
 *   Sound a note of the given frequency for the given time.
 *
 *   The pin drives the base of a transistor through a 1 k resistor and the
 *   buzzer hangs off 3.3 V, so a square wave on the pin is a square wave
 *   across the buzzer.  A passive buzzer follows it and the pitch is the
 *   frequency asked for here; an active one has its own oscillator and will
 *   only be chopped.
 *
 *   Blocking, and deliberately so: a note played from the main loop while
 *   that loop is not otherwise busy.  Anything continuous needs a timer to
 *   toggle the pin instead, which is a separate generator.
 *
 ****************************************************************************/

void stm32n6_buzzer_tone(uint32_t hz, uint32_t ms)
{
  uint32_t half_us;
  uint32_t cycles;
  uint32_t i;

  if (hz == 0 || ms == 0)
    {
      return;
    }

  /* Half a period, in microseconds.  Below 50 Hz this stops being a note
   * and starts being a series of clicks, so the period is capped there.
   */

  half_us = 500000u / hz;
  if (half_us == 0)
    {
      half_us = 1;
    }
  else if (half_us > 10000u)
    {
      half_us = 10000u;
    }

  /* Whole periods, counted in thousandths to stay in 32 bits for the
   * durations this is used for (seconds at most).
   */

  cycles = (ms / 1000u) * hz + ((ms % 1000u) * hz) / 1000u;

  for (i = 0; i < cycles; i++)
    {
      stm32n6_gpiowrite(GPIO_BEEP, true);
      up_udelay(half_us);
      stm32n6_gpiowrite(GPIO_BEEP, false);
      up_udelay(half_us);
    }
}
